            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "An intellectual is a man who says a simple thing in a difficult way; an artist is a man who says a difficult thing in a simple way.", Author = "Charles Bukowski" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "Show me a man who lives alone and has a perpetually clean kitchen, and eight times out of nine I'll show you a man with detestable spiritual qualities.", Author = "Charles Bukowski" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "The free soul is rare, but you know it when you see it - basically because you feel good, very good, when you are near or with them.", Author = "Charles Bukowski" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "It began as a mistake.", Author = "Charles Bukowski" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "Any damn fool can beg up some kind of job; it takes a wise man to make it without working.", Author = "Charles Bukowski" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "I wasn't much of a petty thief. I wanted the whole world or nothing.", Author = "Charles Bukowski" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "Women were meant to suffer; no wonder they asked for constant declarations of love.", Author = "Charles Bukowski" },
