            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "I was a man who thrived on solitude; without it I was like another man without food or water. Each day without solitude weakened me. I took no pride in my solitude; but I was dependent on it.", Author = "Charles Bukowski" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Bukowski", Text = "Love is for real people.", Author = "Charles Bukowski" },
